parameters.text:
=FORECAST SUBMITTED FOR RED-TEAMING:
{{ $json.forecast }}

Decompose it and assign the opening investigations.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "forecast_label": {
      "type": "string",
      "description": "What is forecast, e.g. \"India real GDP growth, FY28\""
    },
    "forecast_value": {
      "type": "string",
      "description": "e.g. \"7.0%\""
    },
    "horizon": {
      "type": "string",
      "description": "e.g. \"FY2027-28\""
    },
    "assumptions": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "A1, A2, ..."
          },
          "text": {
            "type": "string",
            "description": "The assumption"
          },
          "load_bearing": {
            "type": "number",
            "description": "0-1"
          }
        },
        "required": [
          "id",
          "text",
          "load_bearing"
        ]
      }
    },
    "tasks": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "agent": {
            "type": "string",
            "enum": [
              "demand",
              "supply",
              "global",
              "data",
              "historian",
              "blackswan",
              "bull"
            ]
          },
          "question": {
            "type": "string",
            "description": "One precise, answerable investigation question"
          },
          "credits": {
            "type": "number",
            "description": "Credits to allocate, 1-4"
          },
          "type": {
            "type": "string",
            "enum": [
              "investigate",
              "challenge"
            ]
          },
          "target_claim_id": {
            "type": "string",
            "description": "Claim id being challenged, e.g. C4 (only for type=challenge)"
          },
          "reason": {
            "type": "string",
            "description": "Why this investigation matters"
          }
        },
        "required": [
          "agent",
          "question",
          "credits"
        ]
      }
    }
  },
  "required": [
    "forecast_label",
    "forecast_value",
    "assumptions",
    "tasks"
  ]
}

{
  "type": "object",
  "properties": {
    "headline": {
      "type": "string",
      "description": "One-line conclusion, max 14 words"
    },
    "stance": {
      "type": "string",
      "enum": [
        "attacks",
        "supports",
        "neutral"
      ],
      "description": "Effect on the forecast"
    },
    "target_assumption": {
      "type": "string",
      "description": "Assumption id this bears on, e.g. A2"
    },
    "challenges_claim": {
      "type": "string",
      "description": "Claim id you are rebutting, if any"
    },
    "argument": {
      "type": "string",
      "description": "Your argument in 2-5 sentences"
    },
    "causal_mechanism": {
      "type": "string",
      "description": "A -> B -> C transmission to the forecast"
    },
    "confidence": {
      "type": "number",
      "description": "0-1"
    },
    "evidence": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "fact": {
            "type": "string",
            "description": "What the data or source says"
          },
          "source": {
            "type": "string",
            "description": "Publisher / dataset"
          },
          "url": {
            "type": "string",
            "description": "URL returned by a tool, if any"
          },
          "date": {
            "type": "string",
            "description": "Date or period of the data"
          }
        },
        "required": [
          "fact",
          "source"
        ]
      }
    },
    "scenario": {
      "type": "object",
      "description": "Black Swan Agent only",
      "properties": {
        "event": {
          "type": "string",
          "description": "The event"
        },
        "transmission": {
          "type": "string",
          "description": "Transmission mechanism"
        },
        "indicators": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "impact": {
          "type": "string",
          "description": "Economic impact with rough magnitude"
        },
        "probability": {
          "type": "string",
          "description": "Honest probability"
        }
      }
    },
    "indicators_to_watch": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "indicator": {
            "type": "string",
            "description": "Indicator"
          },
          "threshold": {
            "type": "string",
            "description": "e.g. \"> 14%\""
          },
          "direction": {
            "type": "string",
            "enum": [
              "breaks",
              "validates"
            ]
          }
        },
        "required": [
          "indicator",
          "threshold"
        ]
      }
    },
    "follow_ups": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "agent": {
            "type": "string",
            "enum": [
              "demand",
              "supply",
              "global",
              "data",
              "historian",
              "blackswan",
              "bull"
            ]
          },
          "question": {
            "type": "string",
            "description": "One precise, answerable investigation question"
          },
          "credits": {
            "type": "number",
            "description": "Credits to allocate, 1-4"
          },
          "type": {
            "type": "string",
            "enum": [
              "investigate",
              "challenge"
            ]
          },
          "target_claim_id": {
            "type": "string",
            "description": "Claim id being challenged, e.g. C4 (only for type=challenge)"
          },
          "reason": {
            "type": "string",
            "description": "Why this investigation matters"
          }
        },
        "required": [
          "agent",
          "question",
          "credits"
        ]
      }
    },
    "done": {
      "type": "boolean",
      "description": "true if you have enough evidence and need no follow-up"
    }
  },
  "required": [
    "headline",
    "stance",
    "argument",
    "confidence",
    "evidence",
    "done"
  ]
}

{
  "type": "object",
  "properties": {
    "round_summary": {
      "type": "string",
      "description": "2-3 sentences: what this round established"
    },
    "rulings": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "claim_id": {
            "type": "string",
            "description": "e.g. C3"
          },
          "status": {
            "type": "string",
            "enum": [
              "survives",
              "falls",
              "unresolved"
            ]
          },
          "reason": {
            "type": "string",
            "description": "Why"
          },
          "flags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": [
          "claim_id",
          "status",
          "reason"
        ]
      }
    },
    "assumption_status": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "A1"
          },
          "status": {
            "type": "string",
            "description": "untested | holding | under attack | weakened | fragile | broken"
          }
        },
        "required": [
          "id",
          "status"
        ]
      }
    },
    "contradictions": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "between": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "issue": {
            "type": "string",
            "description": "The disagreement"
          },
          "resolving_data": {
            "type": "string",
            "description": "Data that would resolve it"
          }
        },
        "required": [
          "between",
          "issue"
        ]
      }
    },
    "missing_information": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "new_investigations": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "agent": {
            "type": "string",
            "enum": [
              "demand",
              "supply",
              "global",
              "data",
              "historian",
              "blackswan",
              "bull"
            ]
          },
          "question": {
            "type": "string",
            "description": "One precise, answerable investigation question"
          },
          "credits": {
            "type": "number",
            "description": "Credits to allocate, 1-4"
          },
          "type": {
            "type": "string",
            "enum": [
              "investigate",
              "challenge"
            ]
          },
          "target_claim_id": {
            "type": "string",
            "description": "Claim id being challenged, e.g. C4 (only for type=challenge)"
          },
          "reason": {
            "type": "string",
            "description": "Why this investigation matters"
          }
        },
        "required": [
          "agent",
          "question",
          "credits"
        ]
      }
    },
    "robustness_estimate": {
      "type": "number",
      "description": "0-100"
    },
    "sufficient": {
      "type": "boolean"
    }
  },
  "required": [
    "round_summary",
    "rulings",
    "robustness_estimate",
    "sufficient"
  ]
}

{
  "type": "object",
  "properties": {
    "forecast_label": {
      "type": "string",
      "description": "What was forecast"
    },
    "forecast_value": {
      "type": "string",
      "description": "The forecast value"
    },
    "robustness": {
      "type": "number",
      "description": "0-100"
    },
    "confidence": {
      "type": "number",
      "description": "0-100"
    },
    "vulnerability": {
      "type": "string",
      "enum": [
        "LOW",
        "MEDIUM",
        "HIGH",
        "CRITICAL"
      ]
    },
    "verdict": {
      "type": "string",
      "enum": [
        "Robust",
        "Contested",
        "Fragile",
        "Broken"
      ]
    },
    "primary_vulnerability": {
      "type": "string",
      "description": "Primary vulnerability"
    },
    "secondary_vulnerability": {
      "type": "string",
      "description": "Secondary vulnerability"
    },
    "strongest_opposing_evidence": {
      "type": "string",
      "description": "Strongest opposing evidence"
    },
    "strongest_supporting_evidence": {
      "type": "string",
      "description": "Strongest supporting evidence"
    },
    "critical_unknown": {
      "type": "string",
      "description": "Critical unknown"
    },
    "most_dangerous_scenario": {
      "type": "string",
      "description": "Most dangerous scenario"
    },
    "break_conditions": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "break_logic": {
      "type": "string",
      "enum": [
        "AND",
        "OR"
      ]
    },
    "validate_conditions": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "watchlist": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "indicator": {
            "type": "string",
            "description": "Indicator"
          },
          "why": {
            "type": "string",
            "description": "Why it matters"
          },
          "threshold": {
            "type": "string",
            "description": "Threshold to watch"
          }
        },
        "required": [
          "indicator",
          "why"
        ]
      }
    },
    "agent_scores": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "agent": {
            "type": "string",
            "enum": [
              "demand",
              "supply",
              "global",
              "data",
              "historian",
              "blackswan",
              "bull"
            ]
          },
          "reason": {
            "type": "string",
            "description": "Decisive contribution"
          }
        },
        "required": [
          "agent",
          "reason"
        ]
      }
    }
  },
  "required": [
    "robustness",
    "confidence",
    "vulnerability",
    "verdict",
    "primary_vulnerability",
    "break_conditions",
    "validate_conditions",
    "watchlist"
  ]
}
